import{_ as t,H as r,f as o,i}from"./chunks/framework.DLd0CbzH.js";const p=JSON.parse('{"title":"What is HRT? (Trans Female Guide)","description":"A comprehensive guide to feminizing hormone replacement therapy (HRT), including how it works, what to expect, medications, and safety information.","frontmatter":{"title":"What is HRT? (Trans Female Guide)","description":"A comprehensive guide to feminizing hormone replacement therapy (HRT), including how it works, what to expect, medications, and safety information."},"headers":[],"relativePath":"trans-female/intro/what-is-hrt.md","filePath":"trans-female/intro/what-is-hrt.md"}'),a={name:"trans-female/intro/what-is-hrt.md"};function s(n,e,l,d,h,c){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="what-is-hrt-trans-female-guide" tabindex="-1">What is HRT? (Trans Female Guide) <a class="header-anchor" href="#what-is-hrt-trans-female-guide" aria-label="Permalink to &quot;What is HRT? (Trans Female Guide)&quot;">​</a></h1><p><strong>HRT</strong> stands for <strong>Hormone Replacement Therapy</strong>. For trans females, it is a medical treatment that helps align your physical characteristics with your gender identity through the use of hormones such as <strong>estrogen</strong>, <strong>testosterone blockers</strong>, and <strong>progesterone</strong>.</p><h2 id="how-hrt-works" tabindex="-1">How HRT Works <a class="header-anchor" href="#how-hrt-works" aria-label="Permalink to &quot;How HRT Works&quot;">​</a></h2><p>Gender-affirming hormone therapy (GAHT) for trans women typically involves three steps:</p><ol><li><strong>Suppressing testosterone</strong> – Reducing your body&#39;s natural testosterone production to minimise masculine traits.</li><li><strong>Introducing estrogen</strong> – Taking estradiol to promote feminine physical changes.</li><li><strong>Introducing progesterone</strong> – Optionally added later to further support feminine development, particularly breast maturation.</li></ol><p>Estradiol serves two important roles: it directly promotes feminine development, and at sufficient doses it can suppress testosterone on its own.</p><p>Progesterone is not strictly necessary, but some trans women find that adding it:</p><ul><li>Helps round out breast shape (Tanner stage 4/5 development)</li><li>May improve libido, mood, and sleep quality</li><li>May reduce anxiety</li></ul><p>Evidence for progesterone&#39;s benefits is largely anecdotal; clinical studies are limited. Some people experience negative side effects including mood swings, depression, or weight gain. It is typically added after 6–12 months of estrogen therapy.</p><h2 id="what-hrt-does-and-doesn-t-do" tabindex="-1">What HRT Does (and Doesn&#39;t) Do <a class="header-anchor" href="#what-hrt-does-and-doesn-t-do" aria-label="Permalink to &quot;What HRT Does (and Doesn&#39;t) Do&quot;">​</a></h2><h3 id="physical-changes" tabindex="-1">Physical Changes <a class="header-anchor" href="#physical-changes" aria-label="Permalink to &quot;Physical Changes&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Timelines are highly individual</p><p>The ranges below are population-level observations, not predictions for any one person. Onset and progression depend heavily on your regimen, dosage, age, genetics, and overall health. The &quot;typical plateau&quot; column does <strong>not</strong> mean change stops at that point — many people continue to see changes beyond these timeframes, particularly with regimen adjustments. Do not use this table to judge your own progress.</p></div><table tabindex="0"><thead><tr><th>Change</th><th>Typical Onset</th><th>Typical Plateau</th><th>Reversible?</th></tr></thead><tbody><tr><td>Breast development</td><td>3–6 months</td><td>2–3 years*</td><td><strong>No</strong></td></tr><tr><td>Skin softening / decreased oiliness</td><td>3–6 months</td><td>Variable</td><td><strong>Yes</strong></td></tr><tr><td>Body fat redistribution (to hips/thighs)</td><td>3–6 months</td><td>2–5 years*</td><td><strong>Yes</strong> (slowly)</td></tr><tr><td>Decreased muscle mass</td><td>3–6 months</td><td>1–2 years</td><td><strong>Yes</strong></td></tr><tr><td>Reduced body/facial hair growth</td><td>6–12 months</td><td>3+ years</td><td><strong>Partially</strong></td></tr><tr><td>Decreased libido / spontaneous erections</td><td>1–3 months</td><td>1–2 years</td><td><strong>Yes</strong></td></tr><tr><td>Decreased testicular volume</td><td>3–6 months</td><td>2–3 years</td><td><strong>Partially</strong></td></tr><tr><td>Scalp hair loss slowing/reversal</td><td>1–3 months</td><td>1–2 years</td><td><strong>Partially</strong></td></tr></tbody></table><p>* Changes in diet, weight, exercise, or HRT regimen can continue to drive development beyond the typical plateau.</p><div class="danger custom-block"><p class="custom-block-title">Fertility Warning</p><p>Feminising HRT will likely reduce your fertility, possibly permanently. HRT is <strong>not</strong> a contraceptive — use a reliable method of birth control if relevant to you.</p></div><div class="info custom-block"><p class="custom-block-title">Gamete Storage</p><p>If you are considering having biological children in the future, discuss sperm/gamete storage with a healthcare provider <strong>before</strong> starting HRT.</p></div><h3 id="what-hrt-does-not-do" tabindex="-1">What HRT Does NOT Do <a class="header-anchor" href="#what-hrt-does-not-do" aria-label="Permalink to &quot;What HRT Does NOT Do&quot;">​</a></h3><ul><li><strong>Change your voice</strong> — Estrogen does not affect the vocal cords. Voice training or surgery is required.</li><li><strong>Remove facial or body hair</strong> — Estrogen slows hair growth but does not remove existing terminal hair. Laser hair removal or electrolysis is needed for permanent results.</li><li><strong>Guarantee fertility preservation</strong> — HRT significantly reduces sperm production; permanent infertility is possible.</li><li><strong>Shrink your Adam&#39;s apple</strong> — Estrogen does not affect cartilage. Surgical reduction (chondrolaryngoplasty) is the only option.</li></ul><h2 id="key-hormone-targets-monitoring" tabindex="-1">Key Hormone Targets &amp; Monitoring <a class="header-anchor" href="#key-hormone-targets-monitoring" aria-label="Permalink to &quot;Key Hormone Targets &amp; Monitoring&quot;">​</a></h2><p>For feminising GAHT, the Endocrine Society and WPATH SOC8 recommend targeting:</p><ul><li><strong>Testosterone (T)</strong> — below <strong>50 ng/dL</strong></li><li><strong>Estradiol (E2)</strong> — in the cisgender female range, typically <strong>100–200 pg/mL</strong></li></ul><p>Achieving both targets simultaneously is not always possible. <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC10554830/" target="_blank" rel="noreferrer">A Mount Sinai study of 1,195 trans feminine individuals</a> found that:</p><ul><li>Nearly half (43%) of people with E2 below target (&lt;100 pg/mL) still achieved T suppression below 50 ng/dL.</li><li>88.5% of those with E2 above 200 pg/mL achieved T suppression, but some still did not.</li></ul><p>The Endocrine Society recommends monitoring hormone levels <strong>every 3 months</strong> during the first year of therapy, and adjusting doses accordingly.</p><h2 id="common-medications-for-feminising-hrt" tabindex="-1">Common Medications for Feminising HRT <a class="header-anchor" href="#common-medications-for-feminising-hrt" aria-label="Permalink to &quot;Common Medications for Feminising HRT&quot;">​</a></h2><h3 id="estrogen-options" tabindex="-1">Estrogen Options <a class="header-anchor" href="#estrogen-options" aria-label="Permalink to &quot;Estrogen Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Form</th><th>Examples</th><th>VTE Risk</th><th>Notes</th></tr></thead><tbody><tr><td>Oral (pills)</td><td>Estradiol valerate, hemihydrate</td><td>Higher</td><td>2–8 mg/day; can be taken sublingually for better absorption</td></tr><tr><td>Transdermal (gel/patches)</td><td>Oestrogel, patches (50–100 mcg twice weekly)</td><td><strong>Lower</strong></td><td>Preferred by guidelines; steady absorption, less liver impact</td></tr><tr><td>Injections</td><td>Estradiol valerate (EV), cypionate (EC)</td><td>Lower</td><td>2–10 mg weekly or 5–30 mg every 2 weeks</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Transdermal is preferred</p><p>Clinical guidelines recommend transdermal 17β-estradiol over oral formulations, particularly for individuals with elevated cardiovascular or clotting risk, due to its more favourable safety profile.</p></div><h3 id="anti-androgen-testosterone-blocker-options" tabindex="-1">Anti-Androgen (Testosterone Blocker) Options <a class="header-anchor" href="#anti-androgen-testosterone-blocker-options" aria-label="Permalink to &quot;Anti-Androgen (Testosterone Blocker) Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Medication</th><th>Mechanism</th><th>Typical Dose</th><th>Notes</th></tr></thead><tbody><tr><td>Spironolactone</td><td>Blocks androgen receptors; mild T suppression</td><td>50–200 mg/day</td><td>Most common in US; monitor potassium levels, especially in those over 45</td></tr><tr><td>Bicalutamide</td><td>Competitively binds androgen receptors</td><td>25–50 mg/day</td><td>Does not lower T levels; blocks T from binding</td></tr><tr><td>Cyproterone Acetate (CPA)</td><td>Progestogen; suppresses T production</td><td>10–12.5 mg/day</td><td>Effective but associated with meningioma risk at higher doses — see warning below</td></tr><tr><td>GnRH Agonists</td><td>Suppresses pituitary gonadotropins</td><td>Injection every 12 weeks</td><td>Most effective method; expensive and not always accessible</td></tr><tr><td>Finasteride</td><td>5α-reductase inhibitor (blocks DHT conversion)</td><td>1–5 mg/day</td><td>Primarily for scalp hair preservation; not a full anti-androgen</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Cyproterone Acetate (CPA) and Meningioma Risk</p><p>Higher cumulative doses of CPA are associated with a significantly increased risk of meningioma (a type of usually benign brain tumour), with the risk being dose- and duration-dependent. The risk increases particularly with long-term use at doses of 25 mg/day or higher. The current recommended dose for HRT has been lowered to <strong>10–12.5 mg/day</strong> to reduce this risk. CPA is contraindicated in anyone with a history of meningioma.</p></div><div class="info custom-block"><p class="custom-block-title">On Finasteride</p><p>Finasteride is not a primary testosterone blocker for transfeminine HRT. It mainly reduces DHT (dihydrotestosterone), which helps with scalp hair preservation and can modestly slow body-hair progression. It is sometimes used alongside a primary anti-androgen.</p></div><h3 id="monotherapy-estrogen-alone" tabindex="-1">Monotherapy (Estrogen Alone) <a class="header-anchor" href="#monotherapy-estrogen-alone" aria-label="Permalink to &quot;Monotherapy (Estrogen Alone)&quot;">​</a></h3><p>Using only estradiol (without an anti-androgen) is called <strong>monotherapy</strong>. High-dose injectable or transdermal estradiol can suppress testosterone to female range on its own for some individuals, making monotherapy viable in those cases.</p><div class="danger custom-block"><p class="custom-block-title">Oral Monotherapy Warning</p><p>Do <strong>not</strong> attempt monotherapy with oral estrogen pills alone. Oral estrogen at doses high enough to suppress testosterone carries a significantly elevated risk of blood clots (VTE). Monotherapy is only appropriate with injectable or high-dose transdermal estradiol.</p></div><h2 id="side-effects-risks" tabindex="-1">Side Effects &amp; Risks <a class="header-anchor" href="#side-effects-risks" aria-label="Permalink to &quot;Side Effects &amp; Risks&quot;">​</a></h2><h3 id="venous-thromboembolism-vte-—-blood-clots" tabindex="-1">Venous Thromboembolism (VTE) — Blood Clots <a class="header-anchor" href="#venous-thromboembolism-vte-—-blood-clots" aria-label="Permalink to &quot;Venous Thromboembolism (VTE) — Blood Clots&quot;">​</a></h3><p>The most serious known adverse effect of feminising hormone therapy is <strong>venous thromboembolism (VTE)</strong> — the formation of blood clots in veins.</p><ul><li>Oral estrogen increases VTE risk by producing procoagulant changes in the liver — including increased APC resistance and elevated clotting factors IX and XI — because it undergoes first-pass hepatic metabolism. <sup><a href="#ref-1">[1]</a></sup></li><li>Transdermal estradiol does not undergo first-pass metabolism and is not associated with the same procoagulant changes, making it the lower-risk option. <sup><a href="#ref-1">[1]</a>, <a href="#ref-2">[2]</a></sup></li><li>VTE risk is highest in the first year of hormone therapy and remains elevated thereafter. <sup><a href="#ref-1">[1]</a></sup></li><li>Higher-risk groups include: people over 60, smokers, individuals with obesity, those with a personal or family history of VTE, and those with inherited clotting disorders (e.g. Factor V Leiden, antithrombin deficiency). <sup><a href="#ref-2">[2]</a></sup></li></ul><h3 id="other-side-effects" tabindex="-1">Other Side Effects <a class="header-anchor" href="#other-side-effects" aria-label="Permalink to &quot;Other Side Effects&quot;">​</a></h3><ul><li><strong>Blood pressure:</strong> Estrogen therapy has been associated with increases in systolic blood pressure in some studies, making routine cardiovascular monitoring important. The relationship is complex and not consistent across all studies. <sup><a href="#ref-3">[3]</a></sup></li><li><strong>Triglycerides:</strong> Oral estrogen in particular has been associated with increased triglyceride levels, which may contribute to cardiovascular risk. <sup><a href="#ref-4">[4]</a></sup></li><li><strong>Gallbladder disease:</strong> Estrogen appears to promote gallstone formation by increasing cholesterol saturation in bile. A large study of over 38,000 trans women found a significantly increased risk of gallbladder disease in those on estrogen GAHT. <sup><a href="#ref-5">[5]</a></sup></li><li><strong>Breast cancer:</strong> Trans women on hormone therapy have a higher risk of breast cancer than cisgender men, but a lower risk than cisgender women. The 2019 Dutch nationwide cohort study (n = 2,260) found the risk was roughly 47× higher than cisgender men, but more than 3× lower than cisgender women. <sup><a href="#ref-6">[6]</a></sup></li><li><strong>Elevated prolactin:</strong> Cyproterone acetate and higher estradiol exposure have been associated with elevated prolactin levels in some patients, which should be monitored periodically. <sup><a href="#ref-2">[2]</a></sup></li></ul><h3 id="risk-mitigation" tabindex="-1">Risk Mitigation <a class="header-anchor" href="#risk-mitigation" aria-label="Permalink to &quot;Risk Mitigation&quot;">​</a></h3><ul><li><strong>Use transdermal estradiol</strong> if you have elevated cardiovascular or clotting risk — clinical guidelines strongly recommend this. <sup><a href="#ref-1">[1]</a>, <a href="#ref-2">[2]</a></sup></li><li><strong>Stop smoking</strong> — smoking independently raises VTE and cardiovascular risk, and the combination with oral estrogen is particularly concerning. <sup><a href="#ref-2">[2]</a></sup></li><li><strong>Maintain a healthy weight</strong> and stay physically active to reduce baseline cardiovascular and thrombotic risk.</li><li><strong>Monitor blood pressure and lipids</strong> regularly as recommended by your provider. <sup><a href="#ref-3">[3]</a></sup></li><li><strong>If taking spironolactone</strong>, have potassium checked every 3 months in the first year, then annually. Risk of clinically significant hyperkalemia is low in otherwise healthy individuals under 45, but increases with age. <sup><a href="#ref-7">[7]</a></sup></li><li><strong>Before major surgery</strong>, discuss with your provider whether to temporarily pause oral estrogen — practices vary between clinicians and institutions. <sup><a href="#ref-1">[1]</a></sup></li></ul><h2 id="is-hrt-safe" tabindex="-1">Is HRT Safe? <a class="header-anchor" href="#is-hrt-safe" aria-label="Permalink to &quot;Is HRT Safe?&quot;">​</a></h2><p>The Endocrine Society and other major medical organisations recognise gender-affirming hormone therapy as an evidence-based treatment for gender dysphoria when prescribed and monitored appropriately.</p><p>Research consistently demonstrates that GAHT is associated with improvements in psychological well-being, quality of life, and reductions in gender dysphoria. As with any long-term hormone therapy, ongoing monitoring is important to manage risk.</p><h2 id="how-long-until-changes-are-complete" tabindex="-1">How Long Until Changes Are Complete? <a class="header-anchor" href="#how-long-until-changes-are-complete" aria-label="Permalink to &quot;How Long Until Changes Are Complete?&quot;">​</a></h2><p>Physical changes are typically <strong>fully apparent within 3–5 years</strong>. Individual results vary based on:</p><ul><li>Dosage and route of administration</li><li>Age — younger individuals often see faster changes</li><li>Genetics and overall health</li></ul><h2 id="diy-vs-prescribed-hrt" tabindex="-1">DIY vs Prescribed HRT <a class="header-anchor" href="#diy-vs-prescribed-hrt" aria-label="Permalink to &quot;DIY vs Prescribed HRT&quot;">​</a></h2><h3 id="prescribed-hrt" tabindex="-1">Prescribed HRT <a class="header-anchor" href="#prescribed-hrt" aria-label="Permalink to &quot;Prescribed HRT&quot;">​</a></h3><ul><li>Under supervision of an endocrinologist or knowledgeable provider</li><li>Regular monitoring and dose adjustments</li><li><strong>Pros:</strong> safer, medically supervised; free or low-cost in many healthcare systems</li><li><strong>Cons:</strong> long waiting lists (up to 5–7 years in some countries), gatekeeping barriers, high costs in private systems</li></ul><h3 id="diy-hrt" tabindex="-1">DIY HRT <a class="header-anchor" href="#diy-hrt" aria-label="Permalink to &quot;DIY HRT&quot;">​</a></h3><ul><li>Obtaining medications directly without a prescription</li><li><strong>Pros:</strong> immediate access, full control over your care, often cheaper</li><li><strong>Cons:</strong> requires self-education and personal responsibility for sourcing and blood testing; no medical oversight</li></ul><div class="warning custom-block"><p class="custom-block-title">If you use DIY HRT, you must:</p><ol><li><strong>Test your blood regularly</strong> — at minimum every 3 months during the first year</li><li><strong>Source from reputable vendors</strong> with verified product quality</li><li><strong>Educate yourself thoroughly</strong> — understand dosing, side effects, and emergency warning signs</li></ol></div><h2 id="is-hrt-reversible" tabindex="-1">Is HRT Reversible? <a class="header-anchor" href="#is-hrt-reversible" aria-label="Permalink to &quot;Is HRT Reversible?&quot;">​</a></h2><p><strong>Some effects are permanent or long-lasting:</strong></p><ul><li><strong>Breast development</strong> — permanent once breast tissue forms (may reduce slightly if HRT stops)</li><li><strong>Fertility changes</strong> — may be permanent even after stopping HRT</li><li><strong>Testicular atrophy</strong> — partially reversible but can be long-lasting</li></ul><p><strong>Most other changes reverse if HRT is stopped:</strong></p><ul><li>Fat redistribution, skin softening, reduced muscle mass, and other hormonal effects generally reverse over time, though this can take months to years.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p>The following sources are cited in the <a href="#side-effects-risks">Side Effects &amp; Risks</a> section.</p><ol><li><p><a id="ref-1"></a>Connelly PJ et al. (2021). <em>Managing the risk of venous thromboembolism in transgender adults undergoing hormone therapy.</em> PMC. <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC6628137/" target="_blank" rel="noreferrer">https://pmc.ncbi.nlm.nih.gov/articles/PMC6628137/</a></p></li><li><p><a id="ref-2"></a>Patel N et al. (2024). <em>Gender-affirming hormone therapy in the transgender patient: influence on thrombotic risk.</em> PMC. <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC11665511/" target="_blank" rel="noreferrer">https://pmc.ncbi.nlm.nih.gov/articles/PMC11665511/</a></p></li><li><p><a id="ref-3"></a>Connelly PJ et al. (2021). <em>Blood pressure effects of gender-affirming hormone therapy in transgender and gender-diverse adults.</em> Hypertension (AHA). <a href="https://www.ahajournals.org/doi/10.1161/HYPERTENSIONAHA.120.16839" target="_blank" rel="noreferrer">https://www.ahajournals.org/doi/10.1161/HYPERTENSIONAHA.120.16839</a></p></li><li><p><a id="ref-4"></a>Irwig MS. (2020). <em>Cardiovascular health in transgender people.</em> JCEM. <a href="https://academic.oup.com/jcem/article/105/3/e894/5658514" target="_blank" rel="noreferrer">https://academic.oup.com/jcem/article/105/3/e894/5658514</a></p></li><li><p><a id="ref-5"></a>Collin L et al. (2024). <em>Gallbladder disease in transgender individuals: associations with gender-affirming hormone therapy.</em> International Journal of Transgender Health. <a href="https://www.tandfonline.com/doi/full/10.1080/26895269.2023.2283532" target="_blank" rel="noreferrer">https://www.tandfonline.com/doi/full/10.1080/26895269.2023.2283532</a></p></li><li><p><a id="ref-6"></a>de Blok CJM et al. (2019). <em>Breast cancer risk in transgender people receiving hormone treatment: nationwide cohort study in the Netherlands.</em> BMJ. <a href="https://www.bmj.com/content/365/bmj.l1652" target="_blank" rel="noreferrer">https://www.bmj.com/content/365/bmj.l1652</a></p></li><li><p><a id="ref-7"></a>Warnock JK et al. (2022). <em>The utility of monitoring potassium in transgender, gender diverse, and nonbinary individuals on spironolactone.</em> Oxford Academic. <a href="https://scholarworks.indianapolis.iu.edu/items/cd3646fe-ea49-416d-a289-6c7381f1c5bd" target="_blank" rel="noreferrer">https://scholarworks.indianapolis.iu.edu/items/cd3646fe-ea49-416d-a289-6c7381f1c5bd</a></p></li></ol>',63)])])}const m=t(a,[["render",s]]);export{p as __pageData,m as default};
